ACTIVITY_REPO = "import 'package:supabase_flutter/supabase_flutter.dart';\n\nimport '../core/app_config.dart';\nimport '../core/app_session.dart';\n\nclass ActivityRepository {\n  SupabaseClient get _client => Supabase.instance.client;\n\n  Future<List<Map<String, dynamic>>> activity({\n    String? module,\n    int limit = 100,\n  }) async {\n    if (AppConfig.demoMode) return const [];\n\n    var query = _client\n        .from('activity_feed')\n        .select('id,activity_type,title,description,entity_type,entity_id,metadata,created_at,actor:profiles(full_name)')\n        .eq('club_id', AppSession.instance.clubId);\n\n    if (module != null && module.isNotEmpty && module != 'all') {\n      query = query.eq('metadata->>module_code', module);\n    }\n\n    final response = await query\n        .order('created_at', ascending: false)\n        .limit(limit);\n    return List<Map<String, dynamic>>.from(response);\n  }\n\n  Future<List<Map<String, dynamic>>> notifications({\n    int limit = 200,\n    bool archived = false,\n  }) async {\n    if (AppConfig.demoMode) return const [];\n    var query = _client\n        .from('notifications')\n        .select()\n        .eq('club_id', AppSession.instance.clubId)\n        .eq('profile_id', AppSession.instance.profileId);\n\n    query = archived\n        ? query.not('archived_at', 'is', null)\n        : query.isFilter('archived_at', null);\n\n    final response = await query\n        .order('created_at', ascending: false)\n        .limit(limit);\n    return List<Map<String, dynamic>>.from(response);\n  }\n\n  Future<int> unreadCount() async {\n    if (AppConfig.demoMode) return 0;\n    final response = await _client\n        .from('notifications')\n        .select('id')\n        .eq('club_id', AppSession.instance.clubId)\n        .eq('profile_id', AppSession.instance.profileId)\n        .isFilter('read_at', null)\n        .isFilter('archived_at', null);\n    return (response as List).length;\n  }\n\n  Future<void> markRead(String notificationId, {bool read = true}) async {\n    if (AppConfig.demoMode) return;\n    await _client.rpc(\n      'mark_notification_read_v1',\n      params: {\n        'p_notification': notificationId,\n        'p_read': read,\n      },\n    );\n  }\n\n  Future<int> markAllRead() async {\n    if (AppConfig.demoMode) return 0;\n    final response = await _client.rpc(\n      'mark_all_notifications_read_v1',\n      params: {'target_club': AppSession.instance.clubId},\n    );\n    if (response is num) return response.toInt();\n    return int.tryParse(response?.toString() ?? '') ?? 0;\n  }\n\n  Future<void> archive(String notificationId, {bool archived = true}) async {\n    if (AppConfig.demoMode) return;\n    await _client.rpc(\n      'archive_notification_v1',\n      params: {\n        'p_notification': notificationId,\n        'p_archived': archived,\n      },\n    );\n  }\n\n  Future<Map<String, Map<String, bool>>> notificationPreferences() async {\n    if (AppConfig.demoMode) return const {};\n    final response = await _client\n        .from('notification_preferences')\n        .select('module_code,in_app_enabled,push_enabled')\n        .eq('club_id', AppSession.instance.clubId)\n        .eq('profile_id', AppSession.instance.profileId);\n    final result = <String, Map<String, bool>>{};\n    for (final raw in List<Map<String, dynamic>>.from(response)) {\n      final module = raw['module_code']?.toString() ?? '';\n      if (module.isEmpty) continue;\n      result[module] = {\n        'in_app': raw['in_app_enabled'] != false,\n        'push': raw['push_enabled'] != false,\n      };\n    }\n    return result;\n  }\n\n  Future<void> setNotificationPreference({\n    required String moduleCode,\n    required bool inAppEnabled,\n    required bool pushEnabled,\n  }) async {\n    if (AppConfig.demoMode) return;\n    await _client.rpc(\n      'set_notification_preference_v1',\n      params: {\n        'target_club': AppSession.instance.clubId,\n        'p_module_code': moduleCode,\n        'p_in_app_enabled': inAppEnabled,\n        'p_push_enabled': pushEnabled,\n      },\n    );\n  }\n\n  Future<String?> registerPushDevice({\n    required String platform,\n    required String deviceId,\n    required String pushToken,\n    String? appVersion,\n  }) async {\n    if (AppConfig.demoMode) return null;\n    final response = await _client.rpc(\n      'register_push_device_v1',\n      params: {\n        'target_club': AppSession.instance.clubId,\n        'p_platform': platform,\n        'p_device_id': deviceId,\n        'p_push_token': pushToken,\n        'p_app_version': appVersion,\n      },\n    );\n    return response?.toString();\n  }\n\n  Future<void> deactivatePushDevice(String deviceId) async {\n    if (AppConfig.demoMode) return;\n    await _client.rpc(\n      'deactivate_push_device_v1',\n      params: {\n        'target_club': AppSession.instance.clubId,\n        'p_device_id': deviceId,\n      },\n    );\n  }\n}\n"
NOTIFICATION_LOGIC = "enum NotificationViewFilter { all, unread, urgent }\n\nbool notificationIsUrgent(Map<String, dynamic> row) {\n  final priority = row['priority']?.toString().toLowerCase() ?? 'normal';\n  return priority == 'high' || priority == 'urgent';\n}\n\nbool notificationMatchesFilter(\n  Map<String, dynamic> row,\n  NotificationViewFilter filter,\n) {\n  return switch (filter) {\n    NotificationViewFilter.all => true,\n    NotificationViewFilter.unread => row['read_at'] == null,\n    NotificationViewFilter.urgent => notificationIsUrgent(row),\n  };\n}\n\nString? notificationModuleFromRoute(String? rawRoute) {\n  final route = rawRoute?.trim() ?? '';\n  if (route.isEmpty) return null;\n  final normalized = route.startsWith('/') ? route.substring(1) : route;\n  final first = normalized.split('/').first.toLowerCase();\n  return switch (first) {\n    'dashboard' => 'dashboard',\n    'activity' || 'notifications' => 'activity',\n    'members' || 'member' => 'members',\n    'treasury' => 'treasury',\n    'financial' || 'payments' || 'requests' => 'financial',\n    'fees' => 'fees',\n    'lottery' || 'euromillions' => 'lottery',\n    'events' => 'events',\n    'inventory' || 'assets' || 'shop' || 'bar' => 'inventory',\n    'documents' => 'documents',\n    'communication' => 'communication',\n    'reports' => 'reports',\n    'settings' => 'settings',\n    'emergency' => 'emergency',\n    _ => null,\n  };\n}\n"
PUSH_SERVICE = "import 'dart:async';\n\nimport 'package:firebase_core/firebase_core.dart';\nimport 'package:firebase_messaging/firebase_messaging.dart';\nimport 'package:flutter/foundation.dart';\nimport 'package:shared_preferences/shared_preferences.dart';\nimport 'package:uuid/uuid.dart';\n\nimport '../core/app_config.dart';\nimport '../repositories/activity_repository.dart';\n\nclass PushMessageEvent {\n  const PushMessageEvent({\n    required this.title,\n    required this.body,\n    this.actionRoute,\n  });\n\n  final String title;\n  final String body;\n  final String? actionRoute;\n}\n\nclass PushNotificationService {\n  PushNotificationService._();\n\n  static final PushNotificationService instance = PushNotificationService._();\n\n  final ActivityRepository _repository = ActivityRepository();\n  final StreamController<PushMessageEvent> _foregroundController =\n      StreamController<PushMessageEvent>.broadcast();\n  final StreamController<String> _openedController =\n      StreamController<String>.broadcast();\n\n  StreamSubscription<RemoteMessage>? _foregroundSubscription;\n  StreamSubscription<RemoteMessage>? _openedSubscription;\n  StreamSubscription<String>? _tokenSubscription;\n  bool _initialized = false;\n  String? _initialActionRoute;\n\n  Stream<PushMessageEvent> get foregroundMessages =>\n      _foregroundController.stream;\n  Stream<String> get openedRoutes => _openedController.stream;\n\n  bool get configured => AppConfig.hasFirebaseConfiguration;\n\n  Future<bool> initialize() async {\n    if (_initialized) return configured;\n    _initialized = true;\n    if (AppConfig.demoMode || !configured) return false;\n    if (_platformCode == null) return false;\n\n    try {\n      if (Firebase.apps.isEmpty) {\n        await Firebase.initializeApp(\n          options: FirebaseOptions(\n            apiKey: AppConfig.firebaseApiKey,\n            appId: AppConfig.firebaseAppId,\n            messagingSenderId: AppConfig.firebaseMessagingSenderId,\n            projectId: AppConfig.firebaseProjectId,\n            authDomain: AppConfig.firebaseAuthDomain.isEmpty\n                ? null\n                : AppConfig.firebaseAuthDomain,\n            storageBucket: AppConfig.firebaseStorageBucket.isEmpty\n                ? null\n                : AppConfig.firebaseStorageBucket,\n          ),\n        );\n      }\n\n      final messaging = FirebaseMessaging.instance;\n      _foregroundSubscription = FirebaseMessaging.onMessage.listen((message) {\n        final event = _eventFromMessage(message);\n        _foregroundController.add(event);\n      });\n      _openedSubscription = FirebaseMessaging.onMessageOpenedApp.listen((message) {\n        final route = _actionRoute(message);\n        if (route != null) _openedController.add(route);\n      });\n      _tokenSubscription = messaging.onTokenRefresh.listen((token) async {\n        try {\n          await _registerToken(token);\n        } catch (_) {\n          // O próximo arranque volta a tentar sem bloquear a aplicação.\n        }\n      });\n\n      final initial = await messaging.getInitialMessage();\n      if (initial != null) _initialActionRoute = _actionRoute(initial);\n\n      final settings = await messaging.getNotificationSettings();\n      if (_isAuthorized(settings.authorizationStatus)) {\n        await _registerCurrentToken();\n      }\n      return true;\n    } catch (_) {\n      return false;\n    }\n  }\n\n  Future<bool> requestPermissionAndRegister() async {\n    if (!await initialize()) return false;\n    try {\n      final settings = await FirebaseMessaging.instance.requestPermission(\n        alert: true,\n        announcement: false,\n        badge: true,\n        carPlay: false,\n        criticalAlert: false,\n        provisional: false,\n        sound: true,\n      );\n      if (!_isAuthorized(settings.authorizationStatus)) return false;\n      await _registerCurrentToken();\n      return true;\n    } catch (_) {\n      return false;\n    }\n  }\n\n  Future<bool> isPermissionGranted() async {\n    if (!configured || AppConfig.demoMode) return false;\n    try {\n      await initialize();\n      final settings = await FirebaseMessaging.instance.getNotificationSettings();\n      return _isAuthorized(settings.authorizationStatus);\n    } catch (_) {\n      return false;\n    }\n  }\n\n  Future<void> disableCurrentDevice() async {\n    if (!configured || AppConfig.demoMode) return;\n    final deviceId = await _deviceId();\n    try {\n      await _repository.deactivatePushDevice(deviceId);\n      await FirebaseMessaging.instance.deleteToken();\n    } catch (_) {\n      // O estado local da caixa de notificações continua funcional.\n    }\n  }\n\n  String? takeInitialActionRoute() {\n    final result = _initialActionRoute;\n    _initialActionRoute = null;\n    return result;\n  }\n\n  Future<void> _registerCurrentToken() async {\n    final messaging = FirebaseMessaging.instance;\n    final token = await messaging.getToken(\n      vapidKey: kIsWeb && AppConfig.firebaseVapidKey.isNotEmpty\n          ? AppConfig.firebaseVapidKey\n          : null,\n    );\n    if (token == null || token.trim().isEmpty) return;\n    await _registerToken(token);\n  }\n\n  Future<void> _registerToken(String token) async {\n    final platform = _platformCode;\n    if (platform == null) return;\n    await _repository.registerPushDevice(\n      platform: platform,\n      deviceId: await _deviceId(),\n      pushToken: token,\n      appVersion: AppConfig.appVersion.isEmpty ? null : AppConfig.appVersion,\n    );\n  }\n\n  Future<String> _deviceId() async {\n    const key = 'bob_push_device_id';\n    final preferences = await SharedPreferences.getInstance();\n    final existing = preferences.getString(key);\n    if (existing != null && existing.isNotEmpty) return existing;\n    final created = const Uuid().v4();\n    await preferences.setString(key, created);\n    return created;\n  }\n\n  String? get _platformCode {\n    if (kIsWeb) return 'web';\n    return switch (defaultTargetPlatform) {\n      TargetPlatform.android => 'android',\n      TargetPlatform.iOS => 'ios',\n      _ => null,\n    };\n  }\n\n  bool _isAuthorized(AuthorizationStatus status) =>\n      status == AuthorizationStatus.authorized ||\n      status == AuthorizationStatus.provisional;\n\n  PushMessageEvent _eventFromMessage(RemoteMessage message) {\n    return PushMessageEvent(\n      title: message.notification?.title ?? 'BOB Manager',\n      body: message.notification?.body ?? 'Nova notificação',\n      actionRoute: _actionRoute(message),\n    );\n  }\n\n  String? _actionRoute(RemoteMessage message) {\n    final route = message.data['action_route']?.toString().trim() ?? '';\n    return route.isEmpty ? null : route;\n  }\n}\n"
PREFS_SCREEN = "import 'package:flutter/material.dart';\n\nimport '../core/app_config.dart';\nimport '../repositories/activity_repository.dart';\nimport '../services/push_notification_service.dart';\n\nclass NotificationPreferencesScreen extends StatefulWidget {\n  const NotificationPreferencesScreen({super.key});\n\n  @override\n  State<NotificationPreferencesScreen> createState() =>\n      _NotificationPreferencesScreenState();\n}\n\nclass _NotificationPreferencesScreenState\n    extends State<NotificationPreferencesScreen> {\n  final ActivityRepository _repository = ActivityRepository();\n  bool _loading = true;\n  bool _devicePushEnabled = false;\n  Map<String, Map<String, bool>> _preferences = {};\n\n  @override\n  void initState() {\n    super.initState();\n    _load();\n  }\n\n  Future<void> _load() async {\n    try {\n      final values = await _repository.notificationPreferences();\n      final deviceEnabled =\n          await PushNotificationService.instance.isPermissionGranted();\n      if (!mounted) return;\n      setState(() {\n        _preferences = values;\n        _devicePushEnabled = deviceEnabled;\n        _loading = false;\n      });\n    } catch (_) {\n      if (mounted) setState(() => _loading = false);\n    }\n  }\n\n  Map<String, bool> _value(String module) =>\n      _preferences[module] ?? const {'in_app': true, 'push': true};\n\n  Future<void> _save(\n    String module, {\n    bool? inApp,\n    bool? push,\n  }) async {\n    final current = _value(module);\n    final nextInApp = inApp ?? current['in_app'] ?? true;\n    final nextPush = nextInApp ? (push ?? current['push'] ?? true) : false;\n    setState(() {\n      _preferences = {\n        ..._preferences,\n        module: {'in_app': nextInApp, 'push': nextPush},\n      };\n    });\n    try {\n      await _repository.setNotificationPreference(\n        moduleCode: module,\n        inAppEnabled: nextInApp,\n        pushEnabled: nextPush,\n      );\n    } catch (error) {\n      if (!mounted) return;\n      ScaffoldMessenger.of(context).showSnackBar(\n        SnackBar(content: Text('Não foi possível guardar: $error')),\n      );\n      await _load();\n    }\n  }\n\n  Future<void> _enableDevicePush() async {\n    final enabled =\n        await PushNotificationService.instance.requestPermissionAndRegister();\n    if (!mounted) return;\n    setState(() => _devicePushEnabled = enabled);\n    ScaffoldMessenger.of(context).showSnackBar(\n      SnackBar(\n        content: Text(\n          enabled\n              ? 'Notificações push ativadas neste dispositivo.'\n              : 'Não foi possível ativar push. Confirma a configuração Firebase e a permissão do sistema.',\n        ),\n      ),\n    );\n  }\n\n  Future<void> _disableDevicePush() async {\n    await PushNotificationService.instance.disableCurrentDevice();\n    if (mounted) setState(() => _devicePushEnabled = false);\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Preferências de notificações')),\n      body: _loading\n          ? const Center(child: CircularProgressIndicator())\n          : ListView(\n              padding: const EdgeInsets.fromLTRB(16, 16, 16, 80),\n              children: [\n                Card(\n                  child: Padding(\n                    padding: const EdgeInsets.all(16),\n                    child: Column(\n                      crossAxisAlignment: CrossAxisAlignment.start,\n                      children: [\n                        Text(\n                          'Push neste dispositivo',\n                          style: Theme.of(context).textTheme.titleMedium?.copyWith(\n                                fontWeight: FontWeight.w800,\n                              ),\n                        ),\n                        const SizedBox(height: 8),\n                        if (!AppConfig.hasFirebaseConfiguration)\n                          const Text(\n                            'A caixa de notificações está ativa. O push fica disponível depois de configurar Firebase/FCM para esta instalação.',\n                          )\n                        else\n                          Text(\n                            _devicePushEnabled\n                                ? 'Este dispositivo está autorizado a receber push.'\n                                : 'Ativa a permissão do sistema e regista este dispositivo.',\n                          ),\n                        const SizedBox(height: 12),\n                        if (AppConfig.hasFirebaseConfiguration)\n                          FilledButton.icon(\n                            onPressed: _devicePushEnabled\n                                ? _disableDevicePush\n                                : _enableDevicePush,\n                            icon: Icon(\n                              _devicePushEnabled\n                                  ? Icons.notifications_off_outlined\n                                  : Icons.notifications_active_outlined,\n                            ),\n                            label: Text(\n                              _devicePushEnabled\n                                  ? 'Desativar neste dispositivo'\n                                  : 'Ativar push neste dispositivo',\n                            ),\n                          ),\n                      ],\n                    ),\n                  ),\n                ),\n                const SizedBox(height: 12),\n                Text(\n                  'Por módulo',\n                  style: Theme.of(context).textTheme.titleLarge,\n                ),\n                const SizedBox(height: 4),\n                const Text(\n                  'A caixa interna é persistente. Podes escolher em que áreas queres também receber alertas push.',\n                ),\n                const SizedBox(height: 10),\n                for (final item in _modules)\n                  Card(\n                    child: Column(\n                      children: [\n                        ListTile(\n                          leading: Icon(item.$3),\n                          title: Text(item.$2),\n                          subtitle: Text(\n                            (_value(item.$1)['in_app'] ?? true)\n                                ? 'Visível na caixa de notificações'\n                                : 'Notificações deste módulo desativadas',\n                          ),\n                        ),\n                        SwitchListTile(\n                          title: const Text('Na aplicação'),\n                          value: _value(item.$1)['in_app'] ?? true,\n                          onChanged: (value) => _save(item.$1, inApp: value),\n                        ),\n                        SwitchListTile(\n                          title: const Text('Push'),\n                          value: (_value(item.$1)['in_app'] ?? true) &&\n                              (_value(item.$1)['push'] ?? true),\n                          onChanged: (_value(item.$1)['in_app'] ?? true)\n                              ? (value) => _save(item.$1, push: value)\n                              : null,\n                        ),\n                      ],\n                    ),\n                  ),\n              ],\n            ),\n    );\n  }\n}\n\nconst _modules = <(String, String, IconData)>[\n  ('general', 'Geral', Icons.notifications_none_outlined),\n  ('members', 'Membros', Icons.groups_outlined),\n  ('treasury', 'Tesouraria e Pagamentos', Icons.account_balance_wallet_outlined),\n  ('fees', 'Quotas', Icons.receipt_long_outlined),\n  ('lottery', 'Euromilhões', Icons.casino_outlined),\n  ('events', 'Eventos', Icons.event_outlined),\n  ('inventory', 'Património, Inventário e Bar', Icons.inventory_2_outlined),\n  ('documents', 'Documentos', Icons.folder_outlined),\n  ('communication', 'Comunicação', Icons.campaign_outlined),\n  ('emergency', 'Emergência', Icons.emergency_outlined),\n  ('settings', 'Administração', Icons.admin_panel_settings_outlined),\n];\n"
NOTIFICATION_SECTION = "class NotificationCenterScreen extends StatefulWidget {\n  const NotificationCenterScreen({super.key});\n\n  @override\n  State<NotificationCenterScreen> createState() =>\n      _NotificationCenterScreenState();\n}\n\nclass _NotificationCenterScreenState extends State<NotificationCenterScreen> {\n  final ActivityRepository _repository = ActivityRepository();\n  late Future<List<Map<String, dynamic>>> _future;\n  NotificationViewFilter _filter = NotificationViewFilter.all;\n  bool _archived = false;\n\n  @override\n  void initState() {\n    super.initState();\n    _reload();\n  }\n\n  void _reload() {\n    _future = _repository.notifications(archived: _archived);\n  }\n\n  Future<void> _markAll() async {\n    await _repository.markAllRead();\n    if (mounted) setState(_reload);\n  }\n\n  Future<void> _toggle(Map<String, dynamic> row) async {\n    await _repository.markRead(\n      row['id'].toString(),\n      read: row['read_at'] == null,\n    );\n    if (mounted) setState(_reload);\n  }\n\n  Future<void> _archive(Map<String, dynamic> row) async {\n    await _repository.archive(\n      row['id'].toString(),\n      archived: !_archived,\n    );\n    if (mounted) setState(_reload);\n  }\n\n  Future<void> _open(Map<String, dynamic> row) async {\n    if (row['read_at'] == null) {\n      await _repository.markRead(row['id'].toString());\n    }\n    final route = row['action_route']?.toString().trim() ?? '';\n    if (!mounted) return;\n    if (route.isNotEmpty) {\n      Navigator.pop(context, route);\n    } else {\n      setState(_reload);\n    }\n  }\n\n  Future<void> _openPreferences() async {\n    await Navigator.of(context).push<void>(\n      MaterialPageRoute(\n        builder: (_) => const NotificationPreferencesScreen(),\n      ),\n    );\n    if (mounted) setState(_reload);\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('Notificações'),\n        actions: [\n          IconButton(\n            tooltip: 'Preferências',\n            onPressed: _openPreferences,\n            icon: const Icon(Icons.tune_outlined),\n          ),\n          TextButton.icon(\n            onPressed: _archived ? null : _markAll,\n            icon: const Icon(Icons.done_all),\n            label: const Text('Marcar todas'),\n          ),\n        ],\n      ),\n      body: FutureBuilder<List<Map<String, dynamic>>>(\n        future: _future,\n        builder: (context, snapshot) {\n          if (snapshot.hasError) {\n            return Center(child: Text('Erro: ${snapshot.error}'));\n          }\n          if (!snapshot.hasData) {\n            return const Center(child: CircularProgressIndicator());\n          }\n          final rows = snapshot.data!;\n          final visibleRows = rows\n              .where((row) => notificationMatchesFilter(row, _filter))\n              .toList();\n          final unreadCount = rows.where((row) => row['read_at'] == null).length;\n          final urgentCount = rows.where(notificationIsUrgent).length;\n\n          return RefreshIndicator(\n            onRefresh: () async {\n              setState(_reload);\n              await _future;\n            },\n            child: ListView(\n              physics: const AlwaysScrollableScrollPhysics(),\n              padding: const EdgeInsets.fromLTRB(12, 12, 12, 80),\n              children: [\n                Card(\n                  child: Padding(\n                    padding: const EdgeInsets.all(12),\n                    child: Wrap(\n                      spacing: 8,\n                      runSpacing: 8,\n                      crossAxisAlignment: WrapCrossAlignment.center,\n                      children: [\n                        FilterChip(\n                          selected: _filter == NotificationViewFilter.all,\n                          label: Text(_archived ? 'Arquivadas' : 'Todas'),\n                          onSelected: (_) => setState(\n                            () => _filter = NotificationViewFilter.all,\n                          ),\n                        ),\n                        FilterChip(\n                          selected: _filter == NotificationViewFilter.unread,\n                          label: Text('Não lidas ($unreadCount)'),\n                          onSelected: (_) => setState(\n                            () => _filter = NotificationViewFilter.unread,\n                          ),\n                        ),\n                        FilterChip(\n                          selected: _filter == NotificationViewFilter.urgent,\n                          label: Text('Prioritárias ($urgentCount)'),\n                          onSelected: (_) => setState(\n                            () => _filter = NotificationViewFilter.urgent,\n                          ),\n                        ),\n                        ActionChip(\n                          avatar: Icon(\n                            _archived\n                                ? Icons.inbox_outlined\n                                : Icons.archive_outlined,\n                          ),\n                          label: Text(\n                            _archived ? 'Ver caixa de entrada' : 'Ver arquivo',\n                          ),\n                          onPressed: () {\n                            setState(() {\n                              _archived = !_archived;\n                              _filter = NotificationViewFilter.all;\n                              _reload();\n                            });\n                          },\n                        ),\n                      ],\n                    ),\n                  ),\n                ),\n                if (visibleRows.isEmpty)\n                  Card(\n                    child: ListTile(\n                      leading: Icon(\n                        _archived\n                            ? Icons.inventory_2_outlined\n                            : Icons.notifications_off_outlined,\n                      ),\n                      title: Text(\n                        _archived\n                            ? 'Não existem notificações arquivadas.'\n                            : 'Não existem notificações neste filtro.',\n                      ),\n                    ),\n                  )\n                else\n                  for (final row in visibleRows)\n                    _NotificationCard(\n                      row: row,\n                      archived: _archived,\n                      onOpen: () => _open(row),\n                      onToggle: () => _toggle(row),\n                      onArchive: () => _archive(row),\n                    ),\n              ],\n            ),\n          );\n        },\n      ),\n    );\n  }\n}\n\nclass _NotificationCard extends StatelessWidget {\n  const _NotificationCard({\n    required this.row,\n    required this.archived,\n    required this.onOpen,\n    required this.onToggle,\n    required this.onArchive,\n  });\n\n  final Map<String, dynamic> row;\n  final bool archived;\n  final VoidCallback onOpen;\n  final VoidCallback onToggle;\n  final VoidCallback onArchive;\n\n  @override\n  Widget build(BuildContext context) {\n    final unread = row['read_at'] == null;\n    final module = row['module_code']?.toString() ?? 'general';\n    final priority = row['priority']?.toString().toLowerCase() ?? 'normal';\n    final colors = Theme.of(context).colorScheme;\n    final accent = _priorityColor(context, priority);\n    final background = unread\n        ? Color.alphaBlend(colors.primary.withValues(alpha: 0.14), colors.surface)\n        : colors.surfaceContainerLow;\n    final hasRoute = (row['action_route']?.toString().trim() ?? '').isNotEmpty;\n\n    return Card(\n      color: background,\n      shape: RoundedRectangleBorder(\n        borderRadius: BorderRadius.circular(14),\n        side: BorderSide(\n          color: unread ? accent.withValues(alpha: 0.9) : colors.outlineVariant,\n          width: unread ? 1.4 : 0.5,\n        ),\n      ),\n      child: IntrinsicHeight(\n        child: Row(\n          crossAxisAlignment: CrossAxisAlignment.stretch,\n          children: [\n            AnimatedContainer(\n              duration: const Duration(milliseconds: 180),\n              width: unread ? 5 : 2,\n              decoration: BoxDecoration(\n                color: unread ? accent : Colors.transparent,\n                borderRadius: const BorderRadius.horizontal(\n                  left: Radius.circular(14),\n                ),\n              ),\n            ),\n            Expanded(\n              child: ListTile(\n                contentPadding: const EdgeInsets.fromLTRB(12, 6, 6, 6),\n                leading: CircleAvatar(\n                  backgroundColor: unread\n                      ? accent.withValues(alpha: 0.16)\n                      : colors.surfaceContainerHighest,\n                  child: Icon(\n                    _moduleIcon(module),\n                    color: unread ? accent : colors.onSurfaceVariant,\n                  ),\n                ),\n                title: Text(\n                  row['title']?.toString() ?? 'Notificação',\n                  style: TextStyle(\n                    fontWeight: unread ? FontWeight.w800 : FontWeight.w500,\n                  ),\n                ),\n                subtitle: Text([\n                  row['body']?.toString(),\n                  _relativeTime(row['created_at']),\n                  if (hasRoute) 'Toca para abrir',\n                ].where((value) => value != null && value.isNotEmpty).join('\\n')),\n                isThreeLine: true,\n                onTap: onOpen,\n                trailing: PopupMenuButton<String>(\n                  onSelected: (value) {\n                    if (value == 'toggle') onToggle();\n                    if (value == 'archive') onArchive();\n                  },\n                  itemBuilder: (context) => [\n                    PopupMenuItem(\n                      value: 'toggle',\n                      child: Text(\n                        unread ? 'Marcar como lida' : 'Marcar como não lida',\n                      ),\n                    ),\n                    PopupMenuItem(\n                      value: 'archive',\n                      child: Text(archived ? 'Restaurar' : 'Arquivar'),\n                    ),\n                  ],\n                ),\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n\n"
SHELL_SCREEN = "import 'dart:async';\n\nimport 'package:flutter/material.dart';\n\nimport '../core/app_session.dart';\nimport '../core/module_definition.dart';\nimport '../core/notification_center.dart';\nimport '../core/permissions.dart';\nimport '../repositories/activity_repository.dart';\nimport '../services/auth_service.dart';\nimport '../services/push_notification_service.dart';\nimport 'activity_screen.dart';\nimport 'login_screen.dart';\nimport 'module_router.dart';\n\nclass ShellScreen extends StatefulWidget {\n  const ShellScreen({super.key});\n\n  @override\n  State<ShellScreen> createState() => _ShellScreenState();\n}\n\nclass _ShellScreenState extends State<ShellScreen> {\n  int selected = 0;\n  final ActivityRepository _activity = ActivityRepository();\n  late Future<int> _unreadFuture;\n  Timer? _badgeTimer;\n  StreamSubscription<PushMessageEvent>? _foregroundPushSubscription;\n  StreamSubscription<String>? _openedPushSubscription;\n\n  @override\n  void initState() {\n    super.initState();\n    _unreadFuture = _activity.unreadCount();\n    _badgeTimer = Timer.periodic(\n      const Duration(seconds: 30),\n      (_) => _refreshUnread(),\n    );\n    WidgetsBinding.instance.addPostFrameCallback((_) => _configurePush());\n  }\n\n  @override\n  void dispose() {\n    _badgeTimer?.cancel();\n    _foregroundPushSubscription?.cancel();\n    _openedPushSubscription?.cancel();\n    super.dispose();\n  }\n\n  List<ModuleDefinition> get _visibleModules {\n    return appModules.where(_canViewModule).toList();\n  }\n\n  bool _canViewModule(ModuleDefinition module) {\n    final session = AppSession.instance;\n    return switch (module.code) {\n      'dashboard' || 'activity' || 'financial' => session.authenticated,\n      'members' => session.can(AppPermission.viewMembers),\n      'treasury' => session.can(AppPermission.viewTreasury),\n      'fees' => session.can(AppPermission.viewFees),\n      'lottery' => session.can(AppPermission.viewLottery),\n      'events' => session.can(AppPermission.viewEvents),\n      'inventory' => session.can(AppPermission.viewInventory),\n      'documents' => session.can(AppPermission.viewDocuments),\n      'communication' => session.can(AppPermission.viewCommunication),\n      'reports' => session.can(AppPermission.viewFinancialReports),\n      'settings' => session.can(AppPermission.manageSettings),\n      'emergency' => session.can(AppPermission.viewEmergencyData),\n      _ => false,\n    };\n  }\n\n  Future<void> _configurePush() async {\n    await PushNotificationService.instance.initialize();\n    if (!mounted) return;\n    _foregroundPushSubscription ??=\n        PushNotificationService.instance.foregroundMessages.listen((message) {\n      _refreshUnread();\n      if (!mounted) return;\n      final messenger = ScaffoldMessenger.of(context);\n      messenger.hideCurrentSnackBar();\n      messenger.showSnackBar(\n        SnackBar(\n          content: Text('${message.title}\\n${message.body}'),\n          action: message.actionRoute == null\n              ? null\n              : SnackBarAction(\n                  label: 'Abrir',\n                  onPressed: () => _openActionRoute(message.actionRoute!),\n                ),\n        ),\n      );\n    });\n    _openedPushSubscription ??=\n        PushNotificationService.instance.openedRoutes.listen(_openActionRoute);\n    final initialRoute =\n        PushNotificationService.instance.takeInitialActionRoute();\n    if (initialRoute != null) await _openActionRoute(initialRoute);\n  }\n\n  void _refreshUnread() {\n    if (!mounted) return;\n    setState(() => _unreadFuture = _activity.unreadCount());\n  }\n\n  Future<void> _refreshPermissions() async {\n    await AuthService.instance.refreshPermissions();\n    if (!mounted) return;\n    setState(() {\n      _unreadFuture = _activity.unreadCount();\n      final modules = _visibleModules;\n      if (selected >= modules.length) selected = 0;\n    });\n  }\n\n  Future<void> _openNotifications() async {\n    final route = await Navigator.of(context).push<String>(\n      MaterialPageRoute(builder: (_) => const NotificationCenterScreen()),\n    );\n    if (!mounted) return;\n    _refreshUnread();\n    if (route != null) await _openActionRoute(route);\n  }\n\n  Future<void> _openActionRoute(String route) async {\n    final code = notificationModuleFromRoute(route);\n    if (code == null || !mounted) return;\n    final modules = _visibleModules;\n    final index = modules.indexWhere((module) => module.code == code);\n    if (index < 0) return;\n    setState(() => selected = index);\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final modules = _visibleModules;\n    if (modules.isEmpty) {\n      return const Scaffold(\n        body: Center(child: Text('Não existem módulos disponíveis.')),\n      );\n    }\n\n    if (selected >= modules.length) selected = 0;\n    final module = modules[selected];\n    final session = AppSession.instance;\n\n    return Scaffold(\n      appBar: AppBar(\n        title: Text(module.title),\n        actions: [\n          FutureBuilder<int>(\n            future: _unreadFuture,\n            builder: (context, snapshot) {\n              final count = snapshot.data ?? 0;\n              return IconButton(\n                tooltip: count > 0 ? '$count notificações por ler' : 'Notificações',\n                onPressed: _openNotifications,\n                icon: Badge(\n                  isLabelVisible: count > 0,\n                  label: Text(count > 99 ? '99+' : '$count'),\n                  child: const Icon(Icons.notifications_none_outlined),\n                ),\n              );\n            },\n          ),\n          IconButton(\n            tooltip: 'Atualizar permissões',\n            onPressed: _refreshPermissions,\n            icon: const Icon(Icons.refresh),\n          ),\n        ],\n      ),\n      drawer: NavigationDrawer(\n        selectedIndex: selected,\n        onDestinationSelected: (index) {\n          setState(() => selected = index);\n          Navigator.pop(context);\n        },\n        children: [\n          Padding(\n            padding: const EdgeInsets.fromLTRB(24, 24, 24, 12),\n            child: Column(\n              crossAxisAlignment: CrossAxisAlignment.start,\n              children: [\n                const Text(\n                  'BLUE ON BLACK',\n                  style: TextStyle(fontWeight: FontWeight.w900, fontSize: 18),\n                ),\n                const SizedBox(height: 8),\n                Text(\n                  session.fullName,\n                  maxLines: 1,\n                  overflow: TextOverflow.ellipsis,\n                  style: Theme.of(context).textTheme.bodyMedium,\n                ),\n                Text(session.role, style: Theme.of(context).textTheme.bodySmall),\n              ],\n            ),\n          ),\n          const Divider(),\n          ...modules.map(\n            (item) => NavigationDrawerDestination(\n              icon: Icon(item.icon),\n              label: Text(item.title),\n            ),\n          ),\n          const Divider(),\n          ListTile(\n            leading: const Icon(Icons.logout),\n            title: const Text('Terminar sessão'),\n            onTap: () async {\n              await AuthService.instance.signOut();\n              if (!context.mounted) return;\n              Navigator.pushAndRemoveUntil(\n                context,\n                MaterialPageRoute(builder: (_) => const LoginScreen()),\n                (_) => false,\n              );\n            },\n          ),\n        ],\n      ),\n      body: ModuleRouter(module: module),\n    );\n  }\n}\n"
TEST_CONTENT = "import 'package:bob_manager_mobile/core/notification_center.dart';\nimport 'package:flutter_test/flutter_test.dart';\n\nvoid main() {\n  test('filtro unread mostra apenas notificações não lidas', () {\n    expect(\n      notificationMatchesFilter(\n        {'read_at': null, 'priority': 'normal'},\n        NotificationViewFilter.unread,\n      ),\n      isTrue,\n    );\n    expect(\n      notificationMatchesFilter(\n        {'read_at': '2026-08-11T10:00:00Z', 'priority': 'normal'},\n        NotificationViewFilter.unread,\n      ),\n      isFalse,\n    );\n  });\n\n  test('high e urgent são prioridades destacadas', () {\n    expect(notificationIsUrgent({'priority': 'high'}), isTrue);\n    expect(notificationIsUrgent({'priority': 'urgent'}), isTrue);\n    expect(notificationIsUrgent({'priority': 'normal'}), isFalse);\n  });\n\n  test('rota financeira abre Pedidos e Pagamentos', () {\n    expect(notificationModuleFromRoute('/financial'), 'financial');\n  });\n\n  test('rota Euromilhões é normalizada para lottery', () {\n    expect(notificationModuleFromRoute('/euromillions/draw/123'), 'lottery');\n  });\n\n  test('rota desconhecida não força navegação', () {\n    expect(notificationModuleFromRoute('/nao-existe/123'), isNull);\n  });\n}\n"
DOC_CONTENT = '# Commit 10 — Notificações push + centro persistente\n\n## Objetivo\n\nConsolidar a tabela `notifications` como caixa persistente por utilizador e acrescentar entrega push por dispositivo através de Firebase Cloud Messaging (FCM), sem perder notificações quando a entrega externa falha.\n\n## Fluxo\n\n1. O domínio cria uma linha em `notifications`.\n2. O utilizador vê sempre a notificação na caixa interna quando o módulo está ativo nas preferências.\n3. Se `push_enabled=true` e existir um dispositivo FCM ativo, o trigger cria uma linha por dispositivo em `push_deliveries`.\n4. `pg_net` chama a Edge Function `push-dispatch` de forma assíncrona.\n5. A Edge Function valida a capability aleatória da entrega, reclama atomicamente a linha, envia por FCM HTTP v1 e grava `sent`, `failed`, `deferred` ou `skipped`.\n6. Tokens FCM explicitamente inválidos são desativados no servidor.\n\n## Segurança\n\n- Tokens de dispositivo ficam em `push_devices` com RLS de próprio utilizador.\n- O cliente nunca recebe credenciais de servidor Firebase.\n- `claim_push_delivery_v1`, `complete_push_delivery_v1` e funções internas só podem ser executadas pelo `service_role`/triggers.\n- A Edge Function não aceita um ID isolado: exige `delivery_id + dispatch_token` gerados pela base de dados.\n- A notificação persistente não depende do sucesso do push.\n\n## Configuração Firebase necessária para entrega real\n\nA infraestrutura pode existir sem Firebase configurado. Nesse estado a caixa interna funciona normalmente e a Edge Function marca tentativas como `deferred`.\n\nNo cliente Flutter são usados `firebase_core` e `firebase_messaging`. A instalação deve fornecer os `dart-define` Firebase descritos em `AppConfig`, ou ser adaptada posteriormente para o `firebase_options.dart` produzido por `flutterfire configure`.\n\nNo Supabase é necessário guardar como secret da Edge Function:\n\n`FCM_SERVICE_ACCOUNT_JSON=<JSON completo da service account Firebase>`\n\nNunca colocar este JSON no Git.\n\nPara iOS, ativar Push Notifications e Background Modes/Remote notifications no Xcode e associar a chave APNs ao projeto Firebase. Para Android 13+ o utilizador terá de conceder a permissão de notificações.\n\n## Centro persistente\n\n- badge global de não lidas;\n- filtros Todas / Não lidas / Prioritárias;\n- arquivo e restauro;\n- marcar individual ou todas como lidas;\n- preferências por módulo para caixa interna e push;\n- navegação para o módulo indicado em `action_route`;\n- atualização periódica do badge e atualização imediata quando chega uma mensagem FCM em foreground.\n'

def replace_once(path: Path, old: str, new: str):
    text = path.read_text(encoding="utf-8")
    if new in text:
        return
    if old not in text:
        raise SystemExit(f"Bloco esperado não encontrado em {path}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")

